import{_ as a}from"./chunks/thumb-08.CPWc_IRI.js";import{_ as r}from"./chunks/photo-11.CbCHdSaC.js";import{_ as e,H as o,f as s,i}from"./chunks/framework.Cvt1eIE0.js";const u=JSON.parse('{"title":"关税热搜下的消费电子：评论不是站队，而是看清单","description":"","frontmatter":{"title":"关税热搜下的消费电子：评论不是站队，而是看清单","date":"2026-05-12T00:00:00.000Z","category":"阅读","tags":["阅读","评论","宏观"],"excerpt":"关税与供应链话题刷屏时，比情绪更重要的是：谁承担成本、谁有替代方案、谁在转移风险。"},"headers":[],"relativePath":"posts/阅读/tariff-tech-supply-chain-2026.md","filePath":"posts/阅读/tariff-tech-supply-chain-2026.md"}'),n={name:"posts/阅读/tariff-tech-supply-chain-2026.md"};function d(p,t,l,h,c,_){return o(),s("div",null,[...t[0]||(t[0]=[i('<img src="'+a+'" alt="配图" class="article-banner" loading="lazy"><div class="figure wide"><img src="'+r+'" alt="随拍配图" loading="lazy"><p class="figure-caption">全球链条上，没有一条新闻只发生在头条里。</p></div><h1 id="关税热搜下的消费电子" tabindex="-1">关税热搜下的消费电子 <a class="header-anchor" href="#关税热搜下的消费电子" aria-label="Permalink to &quot;关税热搜下的消费电子&quot;">​</a></h1><p>每当贸易政策成为热搜，评论区会自动分成两派：一派喊「脱钩必胜」，一派喊「消费者买单」。<strong>两派都可能对，也都可能漏掉关键变量</strong>——时间尺度与产业链弹性。</p><h2 id="热搜里常被忽略的三件事" tabindex="-1">热搜里常被忽略的三件事 <a class="header-anchor" href="#热搜里常被忽略的三件事" aria-label="Permalink to &quot;热搜里常被忽略的三件事&quot;">​</a></h2><p><strong>1. 成本传递不是瞬间完成的</strong><br> 库存、长单合同、汇率对冲都会推迟终端价格波动。把「今天上热搜」等同于「明天涨价」，容易误判。</p><p><strong>2. 替代方案有门槛</strong><br> 东南亚组装、本地化零部件、软件服务化——听起来简单，实则涉及认证、良率、工程师密度与物流冗余。热搜很少给你看<strong>18 个月的迁移表</strong>。</p><p><strong>3. 小公司更脆弱</strong><br> 巨头可以分摊、对冲、游说；独立开发者和硬件创业团队往往在现金流和单一供应商上更脆。宏观新闻对他们不是背景，是生存条件。</p><h2 id="作为技术读者的评论框架" tabindex="-1">作为技术读者的评论框架 <a class="header-anchor" href="#作为技术读者的评论框架" aria-label="Permalink to &quot;作为技术读者的评论框架&quot;">​</a></h2><p>不必在一条推文里选边。更有用的是问：</p><table tabindex="0"><thead><tr><th>问题</th><th>为什么重要</th></tr></thead><tbody><tr><td>哪些 SKU 先涨价？</td><td>决定用户感知</td></tr><tr><td>哪些组件有第二来源？</td><td>决定恢复速度</td></tr><tr><td>软件订阅能否稀释硬件依赖？</td><td>决定商业模式韧性</td></tr></tbody></table><h2 id="收束" tabindex="-1">收束 <a class="header-anchor" href="#收束" aria-label="Permalink to &quot;收束&quot;">​</a></h2><p>热搜提供情绪，<strong>BOM 表和季度财报</strong>提供证据。把评论写成「谁受损、谁受益、多久传导」，比重复口号更接近真实世界。</p><hr><p><em>宏观随时间变化，本文仅记录观察框架。</em></p>',15)])])}const b=e(n,[["render",d]]);export{u as __pageData,b as default};
